CREATE TRIGGER approval_target BEFORE INSERT ON access_grant_source_approval WHEN NOT EXISTS(SELECT 1 FROM access_grant g JOIN note_version v ON v.org_id=g.org_id AND v.id=NEW.source_note_version_id WHERE g.org_id=NEW.org_id AND g.id=NEW.grant_id AND v.employee_id=NEW.employee_id AND v.category=NEW.source_category AND v.status='published' AND ((g.capability='note.publish' AND g.category IN('shared','manager_private','hr_confidential')) OR (g.capability='action.write' AND g.category='shared')) AND g.purpose='interview_followup' AND g.scope_kind='employee' AND g.employee_id=NEW.employee_id AND (g.object_kind IS NULL OR g.object_employee_id=NEW.employee_id)) OR (SELECT count(*) FROM access_grant_source_approval WHERE org_id=NEW.org_id AND grant_id=NEW.grant_id)>=10 BEGIN SELECT RAISE(ABORT,'invalid source approval'); END;
