ALTER TABLE oidc_transaction_v11 RENAME TO oidc_transaction;
CREATE INDEX oidc_transaction_expiry ON oidc_transaction(expires_at);
CREATE TRIGGER grant_invalidates_assessment AFTER UPDATE ON access_grant WHEN COALESCE(NEW.employee_id,NEW.object_employee_id) IS NOT NULL BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND status IN('approved','consumed'); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='authorization_changed' WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND state IN('queued','leased'); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND status IN('draft','published'); END;
CREATE TRIGGER grant_invalidates_proposed_assessment AFTER UPDATE ON access_grant WHEN COALESCE(NEW.employee_id,NEW.object_employee_id) IS NOT NULL BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND status='proposed'; END;
CREATE TRIGGER grant_change_invalidates_all_assessment AFTER UPDATE ON access_grant BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND status IN('proposed','approved','consumed') AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id)); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='authorization_changed' WHERE org_id=NEW.org_id AND state IN('queued','leased') AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id)); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND status IN('draft','published') AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id)); END;
CREATE TRIGGER grant_insert_invalidates_all_assessment AFTER INSERT ON access_grant BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND status IN('proposed','approved','consumed') AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id)); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='authorization_changed' WHERE org_id=NEW.org_id AND state IN('queued','leased') AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id)); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND status IN('draft','published') AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id)); END;
CREATE TRIGGER grant_bumps_assessment_epoch AFTER INSERT ON access_grant BEGIN INSERT INTO assessment_source_epoch(org_id,employee_id,epoch) SELECT NEW.org_id,e.id,1 FROM employee e WHERE e.org_id=NEW.org_id AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR e.id=COALESCE(NEW.employee_id,NEW.object_employee_id)) ON CONFLICT(org_id,employee_id) DO UPDATE SET epoch=epoch+1; END;
CREATE TRIGGER grant_update_bumps_assessment_epoch AFTER UPDATE ON access_grant BEGIN INSERT INTO assessment_source_epoch(org_id,employee_id,epoch) SELECT NEW.org_id,e.id,1 FROM employee e WHERE e.org_id=NEW.org_id AND (COALESCE(NEW.employee_id,NEW.object_employee_id) IS NULL OR e.id=COALESCE(NEW.employee_id,NEW.object_employee_id)) ON CONFLICT(org_id,employee_id) DO UPDATE SET epoch=epoch+1; END;
CREATE TABLE key_rewrap_job(org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('pii','interview','financial')),state TEXT NOT NULL CHECK(state IN('migrating','ready','blocked')),target_kek_id TEXT NOT NULL,target_kek_version INTEGER NOT NULL CHECK(target_kek_version>0),manifest_digest BLOB NOT NULL CHECK(length(manifest_digest)=32),completed INTEGER NOT NULL DEFAULT 0 CHECK(completed>=0),started_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,domain),FOREIGN KEY(org_id) REFERENCES organization(id)) STRICT;
CREATE TABLE key_rewrap_audit(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('pii','interview','financial')),target_kek_id TEXT NOT NULL,target_kek_version INTEGER NOT NULL,manifest_digest BLOB NOT NULL CHECK(length(manifest_digest)=32),completed INTEGER NOT NULL,actor_uid INTEGER NOT NULL CHECK(actor_uid BETWEEN 0 AND 4294967295),actor_host_hash BLOB NOT NULL CHECK(length(actor_host_hash)=32),recorded_at INTEGER NOT NULL,FOREIGN KEY(org_id) REFERENCES organization(id)) STRICT;
CREATE TABLE key_rewrap_approval_audit(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('pii','interview','financial')),target_kek_id TEXT NOT NULL,target_kek_version INTEGER NOT NULL CHECK(target_kek_version>0),manifest_digest BLOB NOT NULL CHECK(length(manifest_digest)=32),kind TEXT NOT NULL CHECK(kind IN('start','renew')),recorded_at INTEGER NOT NULL,FOREIGN KEY(org_id) REFERENCES organization(id)) STRICT;
CREATE TRIGGER rewrap_block_encrypted_payload BEFORE INSERT ON encrypted_payload WHEN EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='pii' AND (state<>'ready' OR target_kek_id<>NEW.kek_id OR target_kek_version<>NEW.kek_version)) BEGIN SELECT RAISE(ABORT,'key maintenance active'); END;
CREATE TRIGGER rewrap_block_organizational_payload BEFORE INSERT ON organizational_payload WHEN EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='pii' AND (state<>'ready' OR target_kek_id<>NEW.kek_id OR target_kek_version<>NEW.kek_version)) BEGIN SELECT RAISE(ABORT,'key maintenance active'); END;
CREATE TRIGGER rewrap_block_interview_payload BEFORE INSERT ON interview_payload WHEN EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='interview' AND (state<>'ready' OR target_kek_id<>NEW.kek_id OR target_kek_version<>NEW.kek_version)) BEGIN SELECT RAISE(ABORT,'key maintenance active'); END;
CREATE TRIGGER rewrap_block_assessment_payload BEFORE INSERT ON assessment_payload WHEN EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='interview' AND (state<>'ready' OR target_kek_id<>NEW.kek_id OR target_kek_version<>NEW.kek_version)) BEGIN SELECT RAISE(ABORT,'key maintenance active'); END;
CREATE TRIGGER rewrap_block_compensation_payload BEFORE INSERT ON compensation_payload WHEN EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='financial' AND (state<>'ready' OR target_kek_id<>NEW.kek_id OR target_kek_version<>NEW.kek_version)) BEGIN SELECT RAISE(ABORT,'key maintenance active'); END;
CREATE TRIGGER rewrap_block_bonus_payload BEFORE INSERT ON bonus_payload WHEN EXISTS(SELECT 1 FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain='financial' AND (state<>'ready' OR target_kek_id<>NEW.kek_id OR target_kek_version<>NEW.kek_version)) BEGIN SELECT RAISE(ABORT,'key maintenance active'); END;
CREATE TABLE general_export_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN('organization_management','interview_followup')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),export_id TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,PRIMARY KEY(org_id,subject_id,purpose,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id)) STRICT;
CREATE TABLE audit_outbox(event_id TEXT PRIMARY KEY REFERENCES audit_event(id),org_id TEXT,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','inflight','acked')),attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt>=0),available_at INTEGER NOT NULL,claim_token TEXT,claim_until INTEGER,receipt_id TEXT,receipt_digest BLOB CHECK(receipt_digest IS NULL OR length(receipt_digest)=32),acked_at INTEGER,CHECK((state='pending' AND claim_token IS NULL AND claim_until IS NULL AND receipt_id IS NULL AND receipt_digest IS NULL AND acked_at IS NULL) OR (state='inflight' AND claim_token IS NOT NULL AND claim_until IS NOT NULL AND receipt_id IS NULL AND receipt_digest IS NULL AND acked_at IS NULL) OR (state='acked' AND claim_token IS NULL AND claim_until IS NULL AND receipt_id IS NOT NULL AND receipt_digest IS NOT NULL AND acked_at IS NOT NULL)));
INSERT INTO audit_outbox(event_id,org_id,available_at) SELECT id,org_id,recorded_at FROM audit_event;
CREATE INDEX audit_outbox_delivery ON audit_outbox(state,available_at,event_id);
CREATE INDEX audit_event_page ON audit_event(org_id,recorded_at DESC,id DESC);
CREATE INDEX oidc_transaction_previous ON oidc_transaction(previous_hash);
CREATE INDEX grant_compensation_proposal ON access_grant(org_id,compensation_proposal_id);
CREATE INDEX grant_compensation_event ON access_grant(org_id,compensation_event_id);
CREATE INDEX grant_compensation_term ON access_grant(org_id,compensation_term_id);
CREATE TABLE backup_restore_audit(id TEXT PRIMARY KEY,archive_digest BLOB NOT NULL CHECK(length(archive_digest)=32),actor_uid INTEGER NOT NULL CHECK(actor_uid BETWEEN 0 AND 4294967295),actor_host_hash BLOB NOT NULL CHECK(length(actor_host_hash)=32),revoked_sessions INTEGER NOT NULL CHECK(revoked_sessions>=0),recorded_at INTEGER NOT NULL) STRICT;
